                transition '雪地模式-运行中' first '雪地模式' then '运行中';
                transition '运动模式-运行中' first '运动模式' then '运行中';
                transition '经济模式-运行中' first '经济模式' then '运行中';
                transition '运行中-关机中' first '运行中' then '关机中';
