        succession flow '对象流 29' from '整车动力管理功能流程'::'管理动力输出'.'电机功率' to '整车动力管理功能流程'::'监控能量消耗'.'电机功率';
        succession flow '对象流 30' from '整车动力管理功能流程'::'监控能量消耗'.'能量状态' to '整车动力管理功能流程'::'控制热管理'.'能量状态';
        succession flow '对象流 31' from '整车动力管理功能流程'::'执行再生制动'.'回收能量' to '整车动力管理功能流程'::'监控能量消耗'.'能量状态';
        succession flow '对象流 32' from '整车动力管理功能流程'::'调整动力策略'.'调整后功率' to '整车动力管理功能流程'::'检测关机请求'.'关机信号';
        succession flow '对象流 33' from '整车动力管理功能流程'::'检测关机请求'.'关机信号' to '整车动力管理功能流程'::'保存车辆状态'.'车辆状态数据';
        succession flow '对象流 34' from '整车动力管理功能流程'::'保存车辆状态'.'车辆状态数据' to '整车动力管理功能流程'::'高压下电'.'高压状态';
        succession flow '对象流 35' from '整车动力管理功能流程'::'高压下电'.'高压状态' to '整车动力管理功能流程'::'进入驻车模式'.'驻车状态';
        succession flow '对象流 36' from '整车动力管理功能流程'::'进入驻车模式'.'驻车状态' to '整车动力管理功能流程'::'确认关机完成'.'关机完成';
    }
}

