package '整车动力管理_状态机' {
    doc /* 整车动力管理系统状态机行为分析视图 */
    private import ScalarValues::*;
    private import '整车动力管理功能分析'::'整车动力管理功能分析_结构'::*;

    attribute def '点火信号';
    attribute def '自检结果';
    attribute def '驾驶意图';
    attribute def '特殊工况标志';
    attribute def '车辆状态';
    attribute def '关机信号';
    attribute def '关机完成';
    attribute def '确认关机完成';

    port def '点火端口' { in '点火信号输入' : '点火信号'; }
    port def '自检端口' { in '自检结果输入' : '自检结果'; }
    port def '驾驶意图端口' { in '驾驶意图输入' : '驾驶意图'; }
    port def '模式控制端口' { in '特殊工况标志输入' : '特殊工况标志'; in '车辆状态输入' : '车辆状态'; }
    port def '关机端口' { in '关机信号输入' : '关机信号'; in '关机完成输入' : '关机完成'; in '确认关机完成输入' : '确认关机完成'; }

    part def '中央控制系统实例' : '中央控制系统' {
        port '点火端口' : '整车动力管理功能分析'::'整车动力管理_状态机'::'点火端口';
        port '自检端口' : '整车动力管理功能分析'::'整车动力管理_状态机'::'自检端口';
        port '驾驶意图端口' : '整车动力管理功能分析'::'整车动力管理_状态机'::'驾驶意图端口';
        port '模式控制端口' : '整车动力管理功能分析'::'整车动力管理_状态机'::'模式控制端口';
        port '关机端口' : '整车动力管理功能分析'::'整车动力管理_状态机'::'关机端口';

        attribute '电池状态' : Boolean;
        attribute '电池就绪' : Boolean;
        attribute '车辆就绪' : Boolean;
        attribute '高压状态' : Boolean;

        action '执行高压上电';
        action '确认就绪状态';
        action '执行高压下电';
        action '记录故障';
        action '解析驾驶意图';
        action '计算扭矩分配';
        action '激活雪地模式';
        action '激活运动模式';
        action '激活经济模式';
        action '恢复正常动力策略';
        action '保存车辆状态数据';
        action '进入驻车模式';
        action '完成系统断电';

        exhibit state '整车动力管理状态机' {
            doc /* 整车动力管理状态机：描述车辆从关机到运行再到关机的完整生命周期状态转换 */

            state '关机状态' { doc /* 关机状态：车辆完全断电，高压系统下电，处于驻车状态 */ }
            state '启动中' { doc /* 启动中：正在执行点火检测、电池检查、高压上电、系统自检流程 */ }
            state '就绪' { doc /* 就绪：系统自检通过，车辆就绪，等待驾驶意图输入 */ }
            state '运行中' { doc /* 运行中：正常行驶状态，执行扭矩分配、动力输出、能量监控 */ }
            state '雪地模式' { doc /* 雪地模式：特殊工况下的低附着力驾驶模式，动力输出受限 */ }
            state '运动模式' { doc /* 运动模式：特殊工况下的高性能驾驶模式，动力输出增强 */ }
            state '经济模式' { doc /* 经济模式：特殊工况下的节能驾驶模式，优先回收能量 */ }
            state '关机中' { doc /* 关机中：正在执行保存状态、高压下电、进入驻车流程 */ }
            state '驻车' { doc /* 驻车：已完成关机流程，车辆处于安全驻车状态 */ }

            transition '初始转换' first '关机状态' then '启动中';
            transition '关机状态 - 启动中' first '关机状态' accept '点火信号输入' : '点火信号' via '点火端口' if '电池状态' == true do '执行高压上电' then '启动中';
            transition '启动中 - 就绪' first '启动中' accept '自检结果输入' : '自检结果' via '自检端口' if '自检结果输入' == true and '电池就绪' == true do '确认就绪状态' then '就绪';
            transition '启动中 - 关机状态' first '启动中' accept '自检结果输入' : '自检结果' via '自检端口' if '自检结果输入' == false do '执行高压下电' then '关机状态';
            transition '就绪 - 运行中' first '就绪' accept '驾驶意图输入' : '驾驶意图' via '驾驶意图端口' if '驾驶意图输入' != null and '车辆就绪' == true do '解析驾驶意图' then '运行中';
            transition '运行中 - 雪地模式' first '运行中' accept '特殊工况标志输入' : '特殊工况标志' via '模式控制端口' if '特殊工况标志输入' == true and '车辆状态' == snow do '激活雪地模式' then '雪地模式';
            transition '运行中 - 运动模式' first '运行中' accept '特殊工况标志输入' : '特殊工况标志' via '模式控制端口' if '特殊工况标志输入' == true and '车辆状态' == sport do '激活运动模式' then '运动模式';
            transition '运行中 - 经济模式' first '运行中' accept '特殊工况标志输入' : '特殊工况标志' via '模式控制端口' if '特殊工况标志输入' == true and '车辆状态' == eco do '激活经济模式' then '经济模式';
            transition '雪地模式 - 运行中' first '雪地模式' accept '特殊工况标志输入' : '特殊工况标志' via '模式控制端口' if '特殊工况标志输入' == false do '恢复正常动力策略' then '运行中';
            transition '运动模式 - 运行中' first '运动模式' accept '特殊工况标志输入' : '特殊工况标志' via '模式控制端口' if '特殊工况标志输入' == false do '恢复正常动力策略' then '运行中';
            transition '经济模式 - 运行中' first '经济模式' accept '特殊工况标志输入' : '特殊工况标志' via '模式控制端口' if '特殊工况标志输入' == false do '恢复正常动力策略' then '运行中';
            transition '运行中 - 关机中' first '运行中' accept '关机信号输入' : '关机信号' via '关机端口' if '关机信号输入' == true do '保存车辆状态数据' then '关机中';
            transition '关机中 - 驻车' first '关机中' accept '关机完成输入' : '关机完成' via '关机端口' if '关机完成输入' == true and '高压状态' == false do '进入驻车模式' then '驻车';
            transition '驻车 - 关机状态' first '驻车' accept '确认关机完成输入' : '确认关机完成' via '关机端口' if '确认关机完成输入' == true do '完成系统断电' then '关机状态';
        }
    }
}

